# Generated by build.py from recipe.yml for recipe http-time-each-phase-of-a-download. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'slow', 'tls' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'slow/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'tls/hello.txt'), "hello from surl`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -o NUL -w "namelookup %{time_namelookup}\nconnect %{time_connect}\nappconnect %{time_appconnect}\npretransfer %{time_pretransfer}\nstarttransfer %{time_starttransfer}\ntotal %{time_total}\n" http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
